INSERT INTO PBC_FIN_INSTITUTION_ASSET_INFO ( PBC_UUID, TERM_ID, FIN_ASSET_BALANCE, FIN_INS_ASSET_BALANCE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT PBC_UUID, TERM_ID, FIN_ASSET_BALANCE, FIN_INS_ASSET_BALANCE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME FROM ( select TEMP.* from (
select #{item.pbcUuid, jdbcType=VARCHAR } PBC_UUID, #{item.termId, jdbcType=VARCHAR } TERM_ID, #{item.finAssetBalance, jdbcType=DECIMAL } FIN_ASSET_BALANCE, #{item.finInsAssetBalance, jdbcType=DECIMAL } FIN_INS_ASSET_BALANCE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME from dual
) TEMP WHERE NOT EXISTS ( SELECT 1 FROM PBC_FIN_INSTITUTION_ASSET_INFO PFIAI WHERE PFIAI.TERM_ID = TEMP.TERM_ID ) ) de;
UPDATE PBC_FIN_INSTITUTION_ASSET_INFO AS P, ( select T.* from (
select #{item.pbcUuid, jdbcType=VARCHAR } PBC_UUID, #{item.termId, jdbcType=VARCHAR } TERM_ID, #{item.finAssetBalance, jdbcType=DECIMAL } FIN_ASSET_BALANCE, #{item.finInsAssetBalance, jdbcType=DECIMAL } FIN_INS_ASSET_BALANCE, #{item.createUser ,jdbcType=VARCHAR } CREATE_USER, #{item.createDept ,jdbcType=VARCHAR } CREATE_DEPT, #{item.createTime ,jdbcType=TIMESTAMP } CREATE_TIME, #{item.updateUser ,jdbcType=VARCHAR } UPDATE_USER, #{item.updateTime ,jdbcType=TIMESTAMP } UPDATE_TIME from dual
) T ) AS TEMP SET P.PBC_UUID = TEMP.PBC_UUID, P.FIN_ASSET_BALANCE = TEMP.FIN_ASSET_BALANCE, P.FIN_INS_ASSET_BALANCE = TEMP.FIN_INS_ASSET_BALANCE, P.CREATE_USER = TEMP.CREATE_USER, P.CREATE_DEPT = TEMP.CREATE_DEPT, P.CREATE_TIME = TEMP.CREATE_TIME, P.UPDATE_USER = TEMP.UPDATE_USER, P.UPDATE_TIME = TEMP.UPDATE_TIME WHERE P.TERM_ID = TEMP.TERM_ID
